208	    /**
209	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
210	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
211	     * Validation already rejects {@code null} values and the pattern-constrained fields
212	     * when blank, but {@code address} and {@code city} have no pattern, so a
213	     * whitespace-only value would otherwise slip through.
214	     *
215	     * @param ownerFieldsDto the submitted owner fields
216	     * @throws RequiredFieldsMissingException if any required field is missing or blank
217	     */
218	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
219	        List<String> errors = new ArrayList<>();
220	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
221	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
222	        requireText("address", ownerFieldsDto.getAddress(), errors);
223	        requireText("city", ownerFieldsDto.getCity(), errors);
224	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
225	        if (!errors.isEmpty()) {
226	            throw new RequiredFieldsMissingException(errors);
227	        }
228	    }
229	
230	    private static void requireText(String field, String value, List<String> errors) {
231	        if (value == null || value.isBlank()) {
232	            errors.add(field);
233	        }
234	    }
235	
236	    /**
237	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
238	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
239	     * and echoed back in that form.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
243	     *                                        valid E.164 number
244	     */
245	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
246	        String e164 = toE164(ownerFieldsDto.getTelephone());
247	        if (e164 == null) {
248	            throw new RequiredFieldsMissingException(List.of("telephone"));
249	        }
250	        ownerFieldsDto.setTelephone(e164);
251	    }
252	
253	    /**
254	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
255	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
256	     * and country code are present they are kept; otherwise country code {@code '+61'} is
257	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
258	     * must contain 8 to 15 digits after the {@code '+'}.
259	     *
260	     * @param raw the submitted telephone, possibly {@code null}
261	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
262	     */
263	    private static String toE164(String raw) {
264	        if (raw == null) {
265	            return null;
266	        }
267	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
268	        String digits;
269	        if (cleaned.startsWith("+")) {
270	            digits = cleaned.substring(1);
271	        } else {
272	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
273	            digits = "61" + national;
274	        }
275	        if (!digits.matches("[0-9]{8,15}")) {
276	            return null;
277	        }
278	        return "+" + digits;
279	    }
280	
281	    /**
282	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
283	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
284	     * each stored owner's telephone is normalized the same way before comparison so differing
285	     * input formats collapse to the same value.
286	     *
287	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
288	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
289	     *                                     same E.164 telephone
290	     */
291	    /**
292	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
293	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
294	     * the parts may contain whitespace or a second {@code @}.
295	     */
296	    private static final Pattern EMAIL_PATTERN =
297	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
298	
299	    /**
300	     * Normalizes the submitted email when present: the value is trimmed, required to be a
301	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
302	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
303	     *
304	     * @param ownerFieldsDto the submitted owner fields
305	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
306	     */
307	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
308	        String email = ownerFieldsDto.getEmail();
309	        if (email == null) {
310	            return;
311	        }
312	        String trimmed = email.strip();
313	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
314	            throw new InvalidEmailException(email);
315	        }
316	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
317	    }
318	
319	    /**
320	     * Defaults the registration date on create: when the client does not supply a
321	     * {@code registrationDate}, it is set to the server's current date so it is persisted
322	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
323	     *
324	     * @param ownerFieldsDto the submitted owner fields
325	     */
326	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
327	        if (ownerFieldsDto.getRegistrationDate() == null) {
328	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
329	        }
330	    }
331	
332	    /**
333	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'}
334	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
335	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
336	     * (e.g. {@code 'SMI-0007'}).
337	     *
338	     * @param owner the owner being created (with its {@code lastName} already set)
339	     */
340	    private void assignCustomerCode(Owner owner) {
341	        String lastName = owner.getLastName();
342	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
343	        int sequence = this.clinicService.findAllOwners().size() + 1;
344	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
345	    }
346	
347	    private void rejectDuplicateTelephone(String normalizedTelephone) {
348	        boolean duplicate = this.clinicService.findAllOwners().stream()
349	            .map(Owner::getTelephone)
350	            .map(OwnerRestControllerV1::toE164)
351	            .filter(telephone -> telephone != null)
352	            .anyMatch(normalizedTelephone::equals);
353	        if (duplicate) {
354	            throw new DuplicateTelephoneException(normalizedTelephone);
355	        }
356	    }
357	
358	    /**
359	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
360	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
361	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
362	     * still counts as the same household. The check is skipped when the request opts in via
363	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
364	     * the existing one.
365	     *
366	     * @param ownerFieldsDto the submitted owner fields
367	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
368	     *                                     last name and address and the request did not opt in
369	     */
370	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
371	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
372	            return;
373	        }
374	        String lastName = collapse(ownerFieldsDto.getLastName());
375	        String address = collapse(ownerFieldsDto.getAddress());
376	        boolean duplicate = this.clinicService.findAllOwners().stream()
377	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
378	                && collapse(owner.getAddress()).equals(address));
379	        if (duplicate) {
380	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
381	        }
382	    }
383	
384	    /**
385	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
386	     * every internal run of whitespace is collapsed to a single space, and the result is
387	     * lower-cased. A {@code null} value collapses to the empty string.
388	     *
389	     * @param value the value to canonicalize, possibly {@code null}
390	     * @return the collapsed, lower-cased value
391	     */
392	    private static String collapse(String value) {
393	        if (value == null) {
394	            return "";
395	        }
396	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
397	    }
398	
399	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
400	    @Override
401	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
402	        Owner owner = this.clinicService.findOwnerById(ownerId);
403	        if (owner != null) {
404	            Pet pet = owner.getPet(petId);
405	            if (pet != null) {
406	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
407	            }
408	        }
409	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
410	    }
411	}
