375	        String address = collapse(ownerFieldsDto.getAddress());
376	        boolean duplicate = this.clinicService.findAllOwners().stream()
377	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
378	                && collapse(owner.getAddress()).equals(address));
379	        if (duplicate) {
